      const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
      const Value = LocalValue;
      const before = <Choice branch={mode} first={<b>Before module {count}</b>} other={fallback} />;
      return <>{before}<main><Card {...{
      children: ['Spread content ', rows.flatMap(row => [<b key={row.id}>Top {row.name}</b>, <Fragment key={row.id + "-tail"}>Tail {row.value}</Fragment>]), <b key="end">Spread end {count}</b>],
      caption: <span>Spread slot {rows.flatMap(row => [<b key={row.id}>Top {row.name}</b>, <Fragment key={row.id + "-tail"}>Tail {row.value}</Fragment>])}</span>,
    }} {...options} footer={<aside>Footer {account.name}</aside>} />
    <p>Following element {count}</p></main><p>After local shadow {count}</p></>;
    }

