} from './widgets';
type PageProps = Record<string, any>;
type RowData = { id: string; name: string; [key: string]: unknown };

export function Page({ Choice = LocalChoice, ...props }: PageProps) {
      const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
      return <section>Shadowed module <Card {...{
      'children': <section>Quoted property {[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]}</section>,
      [mode]: () => <p>Computed callback {[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]}</p>,
    }} children={<p>Explicit children {count}</p>}>
      Syntactic children {[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]}
    </Card><Value>{account.name}</Value></section>;
    }

