    }} children={<p>Explicit children {count}</p>}>
      Syntactic children {rows.flatMap(row => [<b key={row.id}>Top {row.name}</b>, <Fragment key={row.id + "-tail"}>Tail {row.value}</Fragment>])}
    </Card>);
      return <Shell preview={<p>Final preview {count}</p>}>{result}</Shell>;
    }

